
-- ============================================================
-- TABLE: releases
-- PURPOSE:
-- Stores the current release information obtained from external
-- providers such as AniList and TMDB.
--
-- Each record represents a unique release from a specific
-- provider. The table stores the latest known state of the
-- release and serves as the reference for change detection.
-- ============================================================

CREATE TABLE releases (
    -- Internal identifier generated by PostgreSQL.
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    -- Unique identifier assigned by the external provider.
    external_id BIGINT NOT NULL,

    -- Provider from which the release information originates.
    source VARCHAR(20) NOT NULL,

    -- Release title, preferably in English when available.
    title TEXT NOT NULL,

    -- Release description provided by the external source.
    description TEXT,

    -- Genres associated with the release.
    genres TEXT[] NOT NULL DEFAULT '{}',

    -- URL of the release cover image.
    image_url TEXT,

    -- Confirmed release date (year, month and day).
    release_date DATE,

    -- Current release status reported by the provider.
    status VARCHAR(50) NOT NULL,

    -- Total number of episodes, when available.
    episodes INTEGER,

    -- Duration of each episode or content, in minutes.
    duration INTEGER,

    -- Unix timestamp (seconds) of the last provider update.
    last_provider_update BIGINT,

    -- A provider cannot register the same external release twice.
    CONSTRAINT uq_releases_source_external_id
        UNIQUE (source, external_id),

    -- Only supported providers are allowed.
    CONSTRAINT chk_releases_source
        CHECK (source IN ('AniList', 'TMDB'))
);

-- ============================================================
-- TABLE AND COLUMN DOCUMENTATION
-- ============================================================

COMMENT ON TABLE releases IS
    'Stores the latest known information about releases obtained from external providers.';

COMMENT ON COLUMN releases.id IS
    'Internal primary key generated automatically by PostgreSQL.';

COMMENT ON COLUMN releases.external_id IS
    'Unique identifier assigned to the release by its external provider.';

COMMENT ON COLUMN releases.source IS
    'External provider associated with the release. Supported values: AniList and TMDB.';

COMMENT ON COLUMN releases.title IS
    'Release title. The application prioritizes the English title when available.';

COMMENT ON COLUMN releases.description IS
    'Description of the release obtained from the external provider.';

COMMENT ON COLUMN releases.genres IS
    'Array containing the genres associated with the release.';

COMMENT ON COLUMN releases.image_url IS
    'URL pointing to the release cover image.';

COMMENT ON COLUMN releases.release_date IS
    'Confirmed release date. Only complete dates are stored in this field.';

COMMENT ON COLUMN releases.status IS
    'Current publication or release status reported by the external provider.';

COMMENT ON COLUMN releases.episodes IS
    'Total number of episodes, when provided by the external source.';

COMMENT ON COLUMN releases.duration IS
    'Duration of the content or episode, expressed in minutes, when available.';

COMMENT ON COLUMN releases.last_provider_update IS
    'Unix timestamp in seconds indicating the last update reported by the external provider.';
